        return tuple(row for row in self._rows if row.run_id == run_id)

    def has(self, run_id: str, kind: str) -> bool:
        return any(row.kind == kind for row in self.for_run(run_id))

    def value(self, run_id: str, kind: str) -> str | None:
        matches = [row.value for row in self.for_run(run_id) if row.kind == kind]
        return matches[-1] if matches else None

    def sequence(self, run_id: str) -> tuple[int, ...]:
        return tuple(row.sequence for row in self.for_run(run_id))

    def count(self, run_id: str, kind: str) -> int:
        return sum(row.kind == kind for row in self.for_run(run_id))

    def snapshot(self) -> tuple[dict[str, object], ...]:
        return tuple({"run_id": row.run_id, "kind": row.kind,
                      "value": row.value, "sequence": row.sequence}
