class Queue:
    def __init__(self) -> None:
        self._items: dict[str, WorkItem] = {}
        self._order: list[str] = []

    def put(self, item: WorkItem) -> None:
        if item.run_id not in self._items:
            self._order.append(item.run_id)
        self._items[item.run_id] = item

    def get(self, run_id: str) -> WorkItem:
        return self._items[run_id]

    def first(self) -> WorkItem | None:
        return self._items[self._order[0]] if self._order else None

    def take(self, run_id: str) -> WorkItem:
        item = self._items.pop(run_id)
        self._order.remove(run_id)
        return item

    def names(self) -> tuple[str, ...]:
        return tuple(self._order)

