from mini.model import Decision


def render_review(kind: str, digest: str, decision: Decision,
                  note: str | None = None) -> dict[str, object]:
    if kind not in {"plan", "slice", "final"}:
        raise ValueError("unknown kind")
    if len(digest) != 64:
        raise ValueError("invalid digest")
    body: dict[str, object] = {
        "review_kind": kind,
        "decision": decision.as_row(),
        "validation_digest": digest,
        "complete": kind == "final",
    }
    if note is not None:
        body["note"] = note
    return body


def compact(row: dict[str, object]) -> tuple[str, bool]:
    return str(row["review_kind"]), bool(row["complete"])


def displayed_fields(row: dict[str, object]) -> tuple[str, ...]:
    return tuple(sorted(key for key in row if row[key] is not None))

