import posixpath
from pathlib import PurePosixPath


def normalize(raw: str) -> str:
    if not raw or "\\" in raw or "\x00" in raw:
        raise ValueError("invalid name")
    if PurePosixPath(raw).is_absolute():
        raise ValueError("absolute name")
    value = posixpath.normpath(raw)
    if value in {"", ".", ".."} or value.startswith("../"):
        raise ValueError("outside name")
    return value


def within(raw: str, root: str) -> bool:
    candidate = normalize(raw)
    anchor = normalize(root)
    return candidate == anchor or candidate.startswith(anchor + "/")


def selected(raw: str, roots: tuple[str, ...]) -> str | None:
    matches = [root for root in roots if within(raw, root)]
    if not matches:
        return None
    return max(matches, key=len)


def partition(paths: tuple[str, ...], roots: tuple[str, ...]) -> dict[str, list[str]]:
    result = {root: [] for root in roots}
    for raw in paths:
        root = selected(raw, roots)
        if root is not None:
            result[root].append(normalize(raw))
    return result

