from mini.model import Decision, WorkItem
from mini.store import Gateway, Journal


class Engine:
    def __init__(self, journal: Journal, gateway: Gateway) -> None:
        self.journal = journal
        self.gateway = gateway

    def allowed(self, actor: str, stage: str, action: str) -> bool:
        if action == "edit":
            return actor == "implementer" and stage in {"draft", "slice"}
        if action == "approve":
            return actor == "reviewer" and stage in {"draft", "plan", "slice"}
        if action == "observe":
            return actor in {"reviewer", "operator"}
        return False

    def decide(self, item: WorkItem, action: str) -> Decision:
        allowed = self.allowed(item.actor, item.stage, action)
        reason = "permitted" if allowed else "role or stage unavailable"
        return Decision(allowed, item.actor, item.stage, reason)

    def begin(self, run_id: str) -> str:
        result = self.journal.value(run_id, "completed")
        if result is not None:
            return result
        if self.journal.has(run_id, "requested"):
            raise RuntimeError("outcome unknown")
        self.journal.append(run_id, "requested")
        result = self.gateway.start(run_id)
        self.journal.append(run_id, "completed", result)
        return result

    def resume(self, run_id: str) -> str:
        result = self.journal.value(run_id, "completed")
        if result is not None:
            return result
        if self.journal.has(run_id, "requested"):
            raise RuntimeError("outcome unknown")
        return self.begin(run_id)

    def note(self, run_id: str, value: str) -> None:
        if not value.strip():
            raise ValueError("empty note")
        self.journal.append(run_id, "noted", value)

    def status(self, run_id: str) -> str:
        if self.journal.has(run_id, "completed"):
            return "complete"
        if self.journal.has(run_id, "requested"):
            return "pending"
        return "new"

